def quizzes(items: list[tuple[str, str, str]]) -> str:
    return "".join(
        f'<details class="quiz"><summary>{i}. {level}</summary><p class="quiz-q">{question}</p>'
        f'<p class="quiz-a">{answer} <b>오답 시 다시 볼 곳:</b> 핵심 개념과 실행 결과</p></details>'
        for i, (level, question, answer) in enumerate(items, 1)
    )


def source(slug: str, data: dict) -> str:
    failure_title = "일부러 실패해 보기" if slug.startswith(("01-", "02-")) else "실험 결과 해석"
    failure_body = data.get("failure", data.get("interpretation", ""))
    notebook = f"{{{{notebook:{slug}|example}}}}" if slug.startswith(("01-", "02-")) else f"{{{{notebook:{slug}}}}}"
    failure_notebook = f"{{{{notebook:{slug}|failure}}}}" if slug.startswith(("01-", "02-")) else ""
    notes = "".join(f"<li>{item}</li>" for item in data["notes"])
    summary = "".join(f"<li>{item}</li>" for item in data["summary"])
    goals = "".join(f"<li>{item}</li>" for item in data["goals"])
    refs = COMMON_REFS + data.get("extra_refs", "")
    return f'''<!--meta: {data["meta"]} | 코드 Jupyter Notebook -->
<h2 id="b1"><span class="no">1</span>학습 목표</h2><div class="goal"><ul>{goals}</ul></div>
<h2 id="b2"><span class="no">2</span>이 내용을 배우는 이유</h2><p>{data["why"]}</p>
<h2 id="b3"><span class="no">3</span>앞에서 배운 내용</h2><p>{data["prior"]}</p>
<h2 id="b4"><span class="no">4</span>핵심 개념</h2><h3>쉬운 예</h3><p>{data["analogy"]}</p><h3>정의</h3><p>{data["definition"]}</p><h3>도식 읽기</h3>{{{{svg:{slug[:2]}-흐름}}}}<p>{data["diagram"]}</p>
<h2 id="b5"><span class="no">5</span>실행 예제</h2><p>{data["observe"]}</p>{notebook}<p class="look"><b>확인할 점</b> — {LOOKS[slug]}</p>
<h2 id="b6"><span class="no">6</span>{failure_title}</h2><p>{failure_body}</p>{failure_notebook}
<h2 id="b7"><span class="no">7</span>주의할 점과 실무 메모</h2><ul>{notes}</ul>
<h2 id="b8"><span class="no">8</span>정리와 다음 절</h2><ul>{summary}</ul><p><strong>다음 학습과 이어지는 지점</strong> — {data["next"]}</p>
<h2 id="b9"><span class="no">9</span>복습 문제</h2>{quizzes(data["quiz"])}
<h2 id="b10"><span class="no">10</span>참고 자료</h2><ul>{refs}</ul>'''


def main() -> None:
    config = json.loads((HERE / "chapter.json").read_text(encoding="utf-8"))
    config.update({
        "part_title": "Part 5 · Agent 입문: 프레임워크 없이 먼저",
        "title": "워크플로우 5패턴: 맨손 구현",
        "hours": "총 16h · 강의 4h · 실습 12h",
        "objectives": ["OpenAI SDK와 파이썬 제어문으로 다섯 워크플로우 패턴을 구현할 수 있습니다.", "중간 실패·분류 실패·동점·빈 응답을 숨기지 않고 처리할 수 있습니다.", "같은 과제에서 호출 수·토큰·지연·품질을 비교할 수 있습니다."],
    })
    (HERE / "chapter.json").write_text(json.dumps(config, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    for slug, data in LESSONS.items():
        (HERE / "_src" / f"{slug}.html").write_text(source(slug, data), encoding="utf-8")
    print("wrote", len(LESSONS), "lesson sources")


if __name__ == "__main__":
    main()
